public class Enemy
{
    // Campo público (visible en el Inspector de Unity)
    public int Health = 100;

    // Campo privado con nombre convención _camelCase
    private float _speed = 3.5f;

    // Campo con [SerializeField] (privado pero visible en Inspector)
    [SerializeField]
    private string _name = "Goblin";

    // Campo de solo lectura (se asigna solo en el constructor)
    public readonly int Id;

    // Campo constante (valor fijo en compilación, ALL_CAPS por convención)
    public const int MAX_HEALTH = 200;

    // Campo estático (compartido entre TODOS los objetos Enemy)
    public static int TotalEnemies = 0;
}

